  const PADRAO = ["B3:PETR4", "B3:VALE3", "B3:ITUB4", "B3:BBDC4", "B3:ABEV3", "B3:B3SA3", "B3:WEGE3", "B3:BBAS3", "B3:GGBR4", "B3:MGLU3", "B3:RENT3", "B3:SUZB3"];
  let tickers = ler("babel.bolsa.tickers", PADRAO);
