    if (h.length < 2) return `<svg class="hg-bolsa-spark" viewBox="0 0 120 36" aria-hidden="true"><line x1="0" y1="18" x2="120" y2="18" stroke="rgba(120,170,255,.25)" stroke-dasharray="3 4"/></svg>`;
