    $("#destaques").innerHTML = kpi("Maior alta", esc(porVar[0]?.symbol || "—"), porVar[0] ? `<b>${pct(porVar[0].quote.change_percent)}</b> · ${brl(porVar[0].quote.value)}` : "") + kpi("Maior baixa", esc(porVar[porVar.length - 1]?.symbol || "—"), porVar.length ? `<b class="is-down">${pct(porVar[porVar.length - 1].quote.change_percent)}</b> · ${brl(porVar[porVar.length - 1].quote.value)}` : "") + kpi("Volume da lista", compacto(volume), "ações negociadas hoje") + `<article class="hg-panel hg-kpi"><div class="hg-head"><span class="hg-kpi-label">Sentimento</span></div><div class="hg-bolsa-sentimento"><b class="is-alta">${altas}</b> em alta · <b class="is-baixa">${baixas}</b> em baixa</div><div class="hg-bolsa-barra"><i style="width:${ativos.length ? altas / ativos.length * 100 : 0}%"></i></div></article>`;

