      chipClima.innerHTML = `<span class="ico">${icone}</span><b>${num(c.temp)}°</b><span>${esc(c.description)}</span><small>${esc(st.cidade.nome)} · umidade ${num(c.humidity)}%</small>`;
      chipClima.hidden = false;
